/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  random,
} from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Load font at module level
const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();

// Pre-generate deterministic data for the trading (left) side to avoid mutable state
const CANDLE_COUNT = 600; // Enough to scroll for 60 seconds at fast speed
const CANDLES = Array.from({ length: CANDLE_COUNT }).map((_, i) => {
  // Use a combination of sine waves to create bounded, realistic-looking price movement
  const basePrice =
    Math.sin(i * 0.1) * 150 + Math.cos(i * 0.04) * 100 + 600; // Centered vertically
  const isUp = random(`dir-${i}`) > 0.52; // Slight bias
  const bodySize = random(`bs-${i}`) * 40 + 5;
  const open = basePrice;
  const close = isUp ? open - bodySize : open + bodySize; // Screen Y goes down
  const high = Math.min(open, close) - random(`h-${i}`) * 40;
  const low = Math.max(open, close) + random(`l-${i}`) * 40;
  return { open, close, high, low, isUp };
});

// Pre-generate deterministic particles for the investing (right) side
const INVESTING_PARTICLES = Array.from({ length: 40 }).map((_, i) => ({
  id: i,
  x: random(`px-${i}`), // 0 to 1 relative to container width
  y: random(`py-${i}`), // 0 to 1 relative to container height
  size: random(`ps-${i}`) * 4 + 2,
  speed: random(`psp-${i}`) * 1.5 + 0.5,
  opacity: random(`po-${i}`) * 0.5 + 0.2,
  label: ["YIELD", "ETF", "BOND", "COMPOUND", "INDEX"][i % 5],
  showLabel: random(`pl-${i}`) > 0.8, // Only some have labels
}));

// Path for the long-term investing line chart
const INVESTING_PATH =
  "M 50 850 C 250 850, 400 750, 600 550 S 750 300, 900 150";



export type TradingVsInvestingProps = Record<string, any>;

const TradingVsInvesting: React.FC<TradingVsInvestingProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 12,
  dividerColor = "#ffffff",
  leftLabel = "SHORT-TERM TRADING",
  rightLabel = "LONG-TERM INVESTING",
  tradeUpColor = "#00ff88",
  tradeDownColor = "#ff2a55",
  investingLineColor = "#00bfff",
  investingParticleColor = "#ffffff",
  showParticles = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const totalFrames = durationInSeconds * fps;

  // Parser safety for background
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // GLOBAL ANIMATIONS
  // Smooth camera zoom
  const globalScale = interpolate(frame, [0, totalFrames], [1, 1.04]);
  // Final fade to black
  const globalOpacity = interpolate(
    frame,
    [totalFrames - 30, totalFrames],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // DIVIDER ANIMATION
  const dividerHeight = spring({
    frame: frame - 10,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  const dividerOpacity = interpolate(frame, [10, 30], [0, 0.8], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // LEFT SIDE (TRADING) ANIMATIONS
  const leftOpacity = interpolate(frame, [25, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const scrollX = frame * 18; // Fast scroll speed

  // RIGHT SIDE (INVESTING) ANIMATIONS
  const rightOpacity = interpolate(frame, [35, 60], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  // Evolve path over most of the duration
  const pathProgress = interpolate(frame, [50, totalFrames - 40], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const { strokeDasharray, strokeDashoffset } = evolvePath(
    pathProgress,
    INVESTING_PATH
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <AbsoluteFill
        style={{
          transform: `scale(${globalScale})`,
          opacity: globalOpacity,
          display: "flex",
          flexDirection: "row",
          fontFamily: spaceGrotesk,
          transition: "none",
        }}
      >
        {/* LEFT SIDE: TRADING */}
        <div
          style={{
            flex: 1,
            position: "relative",
            overflow: "hidden",
            opacity: leftOpacity,
          }}
        >
          {/* Fast Moving Grid Background */}
          <div
            style={{
              position: "absolute",
              width: "200%",
              height: "100%",
              background:
                "linear-gradient(90deg, rgba(255,255,255,0.04) 1px, transparent 1px), linear-gradient(0deg, rgba(255,255,255,0.02) 1px, transparent 1px)",
              backgroundSize: "60px 60px",
              transform: `translateX(${-(scrollX % 60)}px)`,
            }}
          />

          {/* Scrolling Candlesticks */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              transform: `translateX(${-scrollX}px)`,
            }}
          >
            {CANDLES.map((candle, i) => {
              const candleColor = candle.isUp ? tradeUpColor : tradeDownColor;
              const xPos = i * 40 + 50; // Spacing of 40px
              return (
                <React.Fragment key={i}>
                  {/* Wick */}
                  <div
                    style={{
                      position: "absolute",
                      left: xPos + 6,
                      top: candle.high,
                      width: 2,
                      height: candle.low - candle.high,
                      backgroundColor: candleColor,
                      boxShadow: `0 0 8px ${candleColor}`,
                    }}
                  />
                  {/* Body */}
                  <div
                    style={{
                      position: "absolute",
                      left: xPos,
                      top: Math.min(candle.open, candle.close),
                      width: 14,
                      height: Math.abs(candle.close - candle.open) || 2,
                      backgroundColor: candleColor,
                      boxShadow: `0 0 12px ${candleColor}`,
                      borderRadius: 2,
                    }}
                  />
                </React.Fragment>
              );
            })}
          </div>

          {/* Left Label */}
          <div
            style={{
              position: "absolute",
              top: height * 0.1,
              left: "50%",
              transform: "translateX(-50%)",
              color: "white",
              fontSize: 32,
              fontWeight: 700,
              letterSpacing: 4,
              textShadow: "0 2px 10px rgba(0,0,0,0.8)",
            }}
          >
            {leftLabel}
          </div>
        </div>

        {/* RIGHT SIDE: INVESTING */}
        <div
          style={{
            flex: 1,
            position: "relative",
            overflow: "hidden",
            opacity: rightOpacity,
          }}
        >
          {/* Subtle slow grid */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              height: "100%",
              background:
                "linear-gradient(0deg, rgba(255,255,255,0.03) 1px, transparent 1px)",
              backgroundSize: "100% 120px",
              transform: `translateY(${(frame * 1) % 120}px)`,
            }}
          />

          {/* Floating Particles & Nodes */}
          {showParticles && (
            <AbsoluteFill>
              {INVESTING_PARTICLES.map((p) => {
                // Particles move slowly upwards
                const currentY =
                  (height + p.y * height - frame * p.speed) % (height * 1.5) -
                  height * 0.2;
                return (
                  <div
                    key={p.id}
                    style={{
                      position: "absolute",
                      left: p.x * (width / 2) * 0.9 + 40,
                      top: currentY,
                      display: "flex",
                      alignItems: "center",
                      gap: 8,
                      opacity: p.opacity,
                    }}
                  >
                    <div
                      style={{
                        width: p.size,
                        height: p.size,
                        backgroundColor: investingParticleColor,
                        borderRadius: "50%",
                        boxShadow: `0 0 10px ${investingParticleColor}`,
                      }}
                    />
                    {p.showLabel && (
                      <span
                        style={{
                          color: investingParticleColor,
                          fontSize: 14,
                          fontWeight: 500,
                          letterSpacing: 1,
                          opacity: 0.7,
                        }}
                      >
                        {p.label}
                      </span>
                    )}
                  </div>
                );
              })}
            </AbsoluteFill>
          )}

          {/* Smooth Evolving Path */}
          <AbsoluteFill>
            <svg width="100%" height="100%" viewBox={`0 0 ${width / 2} ${height}`}>
              <path
                d={INVESTING_PATH}
                fill="none"
                stroke={investingLineColor}
                strokeWidth={6}
                strokeLinecap="round"
                strokeDasharray={strokeDasharray}
                strokeDashoffset={strokeDashoffset}
                style={{
                  filter: `drop-shadow(0px 0px 15px ${investingLineColor})`,
                }}
              />
            </svg>
          </AbsoluteFill>

          {/* Right Label */}
          <div
            style={{
              position: "absolute",
              top: height * 0.1,
              left: "50%",
              transform: "translateX(-50%)",
              color: "white",
              fontSize: 32,
              fontWeight: 700,
              letterSpacing: 4,
              textShadow: "0 2px 10px rgba(0,0,0,0.8)",
            }}
          >
            {rightLabel}
          </div>
        </div>
      </AbsoluteFill>

      {/* CENTER GLOWING DIVIDER */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%) scaleY(${dividerHeight})`,
          width: 2,
          height: height * 0.9,
          backgroundColor: dividerColor,
          opacity: dividerOpacity,
          boxShadow: `0 0 15px ${dividerColor}, 0 0 30px ${dividerColor}`,
          zIndex: 10,
        }}
      />
    </AbsoluteFill>
  );
};

export default TradingVsInvesting;